// План specs/estimates.md 2.1 (#a96197). PROD, admin, компания «test», десктоп, EN. @writes @data: заполняется смета «QA-AUTO est-send #a96197 …»
// (клиент QA-SMS Client), но НЕ сохраняется и НЕ отправляется — Send только открывает окно, затем Cancel; очистка не нужна (записи нет).
// Если запись всё-таки создалась (регресс), тест падает, а в finally смета удаляется/архивируется.
// Источник: «מה רצוי» — ההצעה נשמרת רק כשהמשתמש שולח אותה או לוחץ Save; Cancel בחלון Send מחזיר לטופס בלי ליצור רשומה.
// Факты 17.11: Send не создаёт POST Assessment, Cancel не создаёт EST. Реальный SMS не уходит (Send в окне не нажимается; запрос SMS перехвачен).
import { test, expect } from '../../fixtures';
import {
  QA_SMS_CLIENT, estimateRows, fakeSmsSent, fillEstimate, openNewEstimateForClient, removeEstimate, restoreTest, startInTest,
} from '../estimates-sms-link/estimate-sms-helpers';
import { watchAssessmentWrites } from './estimates-helpers';

test.describe('New Estimate — Send window does not save a draft (#a96197)', () => {
  test('Fill an estimate → Send opens the window with no Assessment POST → Cancel → no new EST in the list #a96197 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const admin = await asUser('admin');
    await startInTest(admin);
    const sms = await fakeSmsSent(admin);
    const title = `QA-AUTO est-send #a96197 ${Date.now().toString(36)}`;
    try {
      await openNewEstimateForClient(admin, QA_SMS_CLIENT.name);
      await fillEstimate(admin, title, { name: 'QA-AUTO item', price: '1' });
      const writes = watchAssessmentWrites(admin);

      await admin.getByRole('button', { name: 'Send', exact: true }).filter({ visible: true }).last().click();
      const dialog = admin.getByRole('dialog', { name: 'Send Estimate' });
      await expect(dialog).toBeVisible();
      await expect.poll(() => writes.length, { message: 'пока окно Send открыто — запросов записи сметы нет', timeout: 3_000 }).toBe(0);

      await dialog.getByRole('button', { name: 'Cancel', exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(admin.getByRole('button', { name: 'Send', exact: true }).filter({ visible: true }).last(), 'вернулись к форме').toBeVisible();
      expect(writes, 'после Cancel записи сметы нет').toEqual([]);
      expect(sms, 'SMS не отправлялось').toEqual([]);

      const rows = await estimateRows(admin, title);
      await expect(rows, 'в Estimates нет черновика с этим заголовком').toHaveCount(0);
    } finally {
      await removeEstimate(admin, title);
      await restoreTest(admin);
    }
  });
});
